test('renderInvoiceText order: discount before VAT, voucher after VAT, due and paid at end', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
    terms: 'NET14',
  });
  assert.equal(invoice.ok, true);

