import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText renders a draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /^DRAFT$/m);
  assert.match(r.value, /^Kite & Co$/m);
  assert.match(r.value, /^5 x Design work \(hour\) @ €85\.00 = €425\.00$/m);
  // VAT on 425 at 21% = 89.25, rounded = 89
  assert.match(r.value, /^VAT: €89\.25$/m);
  assert.match(r.value, /^Total: €514\.25$/m);
});

test('renderInvoiceText renders an issued invoice with number', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(invoice.ok, true);

  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);

  const r = renderInvoiceText(issued.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /^INV-2026-0001$/m);
  assert.match(r.value, /^Kite & Co$/m);
});

test('renderInvoiceText renders multiple line items', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /5 x Design work \(hour\) @ €85\.00 = €425\.00/);
  assert.match(r.value, /10 x Development \(hour\) @ €95\.00 = €950\.00/);
  // VAT: line 1 = 425 * 0.21 = 89.25, line 2 = 950 (bulk discount 2.5%) * 0.21 = 194.50, total = 283.76
  assert.match(r.value, /^VAT: €283\.76$/m);
  assert.match(r.value, /^Total: €1,635\.01$/m);
});

test('renderInvoiceText formats amounts using formatEuros', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
      { sku: 'LOGO-PACK', qty: 1, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  // Logo package is €1,200.00 per unit, so 2 = €2,400.00
  // VAT 21% on 2400 = 504.00, total = 2904.00
  assert.match(r.value, /1 x Logo package @ €1,200\.00 = €1,200\.00/);
  assert.match(r.value, /^VAT: €504\.00$/m);
  assert.match(r.value, /^Total: €2,904\.00$/m);
});

test('renderInvoiceText rejects unknown customer', () => {
  const invoice = {
    customerId: 'C-999',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
  };

  const r = renderInvoiceText(invoice);
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('renderInvoiceText includes customer name', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  const lines = r.value.split('\n');
  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText shows correct line count', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 0 },
      { sku: 'DEV-HOUR', qty: 3, discountPercent: 0 },
      { sku: 'COPY-HOUR', qty: 2, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  const lines = r.value.split('\n');
  // Number line + customer name + 3 items + VAT line + total + due date (default NET30) = 8 lines
  assert.equal(lines.length, 8);
});

test('renderInvoiceText works with items having different VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  // DES-HOUR: 85 * 21% VAT = 17.85
  // PRINT-A4: 37 (bulk discount 2.5%) * 9% VAT = 3.25
  // Total VAT: 21.10
  assert.match(r.value, /Design work \(hour\) @ €85\.00 = €85\.00/);
  assert.match(r.value, /Printed flyer A4 \(each\) @ €0\.37 = €37\.00/);
  assert.match(r.value, /^VAT: €21\.10$/m);
  assert.match(r.value, /^Total: €142\.18$/m);
});

test('renderInvoiceText produces valid text output', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.equal(typeof r.value, 'string');
  assert.ok(r.value.includes('DRAFT'));
  assert.ok(r.value.includes('Kite & Co'));
  assert.ok(r.value.includes('Total:'));
});

test('renderInvoiceText shows line discount when present', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /5 x Design work \(hour\) @ €85\.00 = €425\.00/);
  // 10% discount on 425 = 42.50
  assert.match(r.value, /Discount \(10%\): -€42\.50/);
});

test('renderInvoiceText does not show discount when discountPercent is 0', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  // Should not contain "Discount" line when discount is 0
  assert.ok(!r.value.includes('Discount'));
});

test('renderInvoiceText shows multiple line discounts', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 20 },
    ],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /Discount \(10%\)/);
  assert.match(r.value, /Discount \(20%\)/);
});

test('renderInvoiceText shows voucher when present', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const withVoucher = applyVoucher(invoice.value, { code: 'SUMMER2026', amount: 1000 });
  assert.equal(withVoucher.ok, true);

  const r = renderInvoiceText(withVoucher.value);
  assert.equal(r.ok, true);
  // Voucher shows before Total line
  assert.match(r.value, /Voucher \(SUMMER2026\): -€10\.00/);
  assert.match(r.value, /Total:/);
});

test('renderInvoiceText does not show voucher when not present', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  assert.ok(!r.value.includes('Voucher'));
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(invoice.ok, true);

  const issued = issueInvoice(invoice.value, []);
  assert.equal(issued.ok, true);

  const r = renderInvoiceText(issued.value);
  assert.equal(r.ok, true);
  assert.match(r.value, /^Due: 2026-10-21$/m);
});

test('renderInvoiceText shows due date on draft invoice (default NET30)', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
  });
  assert.equal(invoice.ok, true);

  const r = renderInvoiceText(invoice.value);
  assert.equal(r.ok, true);
  // All invoices have a dueDate (default NET30), so draft invoices also show it
  assert.match(r.value, /^Due: 2026-11-06$/m);
});

test('renderInvoiceText shows paid amount when invoice has payments', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0 }],
