test('renderInvoiceText order: discount before VAT, voucher after VAT, due and paid at end', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
    terms: 'NET14',
  });
  assert.equal(invoice.ok, true);

  let processed = invoice.value;
  const issued = issueInvoice(processed, []);
  processed = issued.value;
  const withVoucher = applyVoucher(processed, { code: 'TEST', amount: 500 });
  processed = withVoucher.value;
  const paid = recordPayment(processed, { amount: 3000, date: '2026-10-08' });
  processed = paid.value;

  const r = renderInvoiceText(processed);
  const lines = r.value.split('\n');

  const discountIdx = lines.findIndex(l => l.includes('Discount'));
  const vatIdx = lines.findIndex(l => l.includes('VAT:'));
  const voucherIdx = lines.findIndex(l => l.includes('Voucher'));
  const totalIdx = lines.findIndex(l => l.includes('Total:'));
  const dueIdx = lines.findIndex(l => l.includes('Due:'));
  const paidIdx = lines.findIndex(l => l.includes('Paid:'));

  // Order should be: discount < VAT < voucher < total < due < paid
  assert.ok(discountIdx < vatIdx, 'Discount should come before VAT');
  assert.ok(vatIdx < voucherIdx, 'VAT should come before voucher');
  assert.ok(voucherIdx < totalIdx, 'Voucher should come before total');
  assert.ok(totalIdx < dueIdx, 'Total should come before due');
  assert.ok(dueIdx < paidIdx, 'Due should come before paid');
});

