test('renderInvoiceText with all features: discount, voucher, due date, paid', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    terms: 'NET14',
  });
  assert.equal(invoice.ok, true);

  let processed = invoice.value;

  // Apply voucher (must be done before issuing)
  const withVoucher = applyVoucher(processed, { code: 'WELCOME', amount: 2500 });
  assert.equal(withVoucher.ok, true);
  processed = withVoucher.value;

  // Issue the invoice
  const issued = issueInvoice(processed, []);
  assert.equal(issued.ok, true);
  processed = issued.value;

  // Record payment
  const paid = recordPayment(processed, { amount: 20000, date: '2026-10-12' });
  assert.equal(paid.ok, true);
  processed = paid.value;

  const r = renderInvoiceText(processed);
  assert.equal(r.ok, true);

  // Check all elements are present
  assert.match(r.value, /INV-2026-0001/);
  assert.match(r.value, /5 x Design work/);
  assert.match(r.value, /Discount \(10%\)/);
  assert.match(r.value, /Voucher \(WELCOME\)/);
  assert.match(r.value, /^Due: 2026-10-21$/m);
  assert.match(r.value, /^Paid: €200\.00$/m);
  assert.match(r.value, /Total:/);
});

